here = os.path.dirname(os.path.abspath(__file__))
for i, code in enumerate(CODES):
    with open(os.path.join(here, code + '.txt'), 'w', encoding='utf-8', newline='\n') as f:
        f.write('# Inoculant: ' + code + ' (made by make_packs.py; English = translation, a line each)\n')
        for en, tr in T.items():
            assert len(tr) == len(CODES), en
            if tr[i] and tr[i] != en: f.write(en + ' = ' + tr[i] + '\n')
print('wrote', len(CODES), 'packs,', len(T), 'lines each')
